build.plugins:
{%- if values.provided_api or values.consumed_apis | length > 0 %}

  io.apicurio
  apicurio-registry-maven-plugin
  ${apicurio.registry.maven.plugin.version}


      download-openapi-contracts
      initialize
      download

        ${schema.registry.api.url}

          {%- if values.provided_api %}

            ${{ values.provided_api.registry_group_id }}
            ${{ values.provided_api.registry_artifact_id }}
            {%- if values.provided_api.version != 'latest' %}
            ${{ values.provided_api.version }}
            {%- endif %}
            ${project.build.directory}/generated-resources/openapi/${{ values.provided_api.contract_file }}
            true

          {%- endif %}
          {%- for consumed_api in values.consumed_apis %}

            ${{ consumed_api.registry_group_id }}
            ${{ consumed_api.registry_artifact_id }}
            {%- if consumed_api.version != 'latest' %}
            ${{ consumed_api.version }}
            {%- endif %}
            ${project.build.directory}/generated-resources/openapi/${{ consumed_api.contract_file }}
            true

          {%- endfor %}





{%- endif %}
{%- if values.provided_api or values.consumed_apis | length > 0 %}

  org.openapitools
  openapi-generator-maven-plugin
  7.8.0

      {%- if values.provided_api %}

          producer-spec
          generate-sources

              generate


              spring
              spring-boot
              ${project.basedir}/target/generated-sources

                  ${project.build.directory}/generated-resources/openapi/${{ values.provided_api.contract_file }}

              true
              false
              false
              false
              false


                  ${project.artifactId}
                  ${project.groupId}
                  ${project.version}
                  true
                  java8
                  src/main/java
                  ${{ values.java_package }}
                  false
                  ${{ values.java_package }}.model
                  none
                  true



      {%- endif %}
      {%- for consumed_api in values.consumed_apis %}

          consumer-${{ consumed_api.alias }}
          generate-sources

              generate


              spring
              spring-boot
              ${project.basedir}/target/generated-sources/${{ consumed_api.alias }}

                  ${project.build.directory}/generated-resources/openapi/${{ consumed_api.contract_file }}

              true
              false
              false
              false
              false


                  ${project.artifactId}
                  ${project.groupId}
                  ${project.version}
                  true
                  java8
                  src/main/java
                  ${{ values.java_package }}.client.${{ consumed_api.alias | replace('-', '') }}
                  false
                  ${{ values.java_package }}.client.${{ consumed_api.alias | replace('-', '') }}.model
                  none
                  true



      {%- endfor %}


{%- endif %}

  org.apache.maven.plugins
  maven-compiler-plugin

    ${java.version}



  org.springframework.boot
  spring-boot-maven-plugin
